// Perceptually uniform colormaps from cmocean (Kristen M. Thyng, MIT).
// https://matplotlib.org/cmocean/, each map is a 256-entry RGB lookup table,
// byte-packed and base64-encoded here so the viewer vendors them as small data
// with no external dependency. Regenerate with the builder in the viewer README.
// SPDX-FileCopyrightText: 2015 Kristen M. Thyng
// SPDX-License-Identifier: MIT

const PACKED = {
  thermal:
    "",
  haline:
    "",
  balance:
    "",
  speed:
    "",
  dense:
    "",
  delta:
    "",
};

function decodeLut(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes; // length 768: [r,g,b] * 256
}

const LUTS = Object.fromEntries(Object.entries(PACKED).map(([name, packed]) => [name, decodeLut(packed)]));

// Diverging maps that read correctly when centred on zero (difference mode).
export const DIVERGING = new Set(["balance", "delta"]);

export const COLORMAP_NAMES = Object.keys(LUTS);

export function lookupTable(name) {
  return LUTS[name] || LUTS.thermal;
}

/**
 * Sample a colormap at a normalised position in [0, 1], clamped.
 * Returns [r, g, b] each 0..255.
 */
export function sample(name, position) {
  const lut = lookupTable(name);
  const clamped = position <= 0 ? 0 : position >= 1 ? 1 : position;
  const index = Math.round(clamped * 255) * 3;
  return [lut[index], lut[index + 1], lut[index + 2]];
}
